package io.amadeus.mobile;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.io.*;
public class MobileDataTest {
 @Test public void scopeSeparatesProjectsAndCharacters() throws Exception {assertEquals("user",MobileData.scope(new JSONObject()));assertEquals("project:laptop:role:alice",MobileData.scope(new JSONObject().put("projectId","laptop").put("roleId","alice")));assertNotEquals(MobileData.scope(new JSONObject().put("roleId","alice")),MobileData.scope(new JSONObject().put("roleId","bob")));}
 @Test public void portableCardRetainsWorldAndIgnoresExecutableFields() throws Exception {JSONObject c=MobileData.parseCard("{\"spec\":\"chara_card_v2\",\"data\":{\"name\":\"Alice\",\"description\":\"Explorer\",\"script\":\"bad()\",\"character_book\":{\"entries\":[]}}}".getBytes(StandardCharsets.UTF_8));assertEquals("Alice",c.getString("name"));assertFalse(c.has("script"));assertTrue(c.has("character_book"));}
 @Test public void worldUsesKeywordsAndHonorsDisabledEntries() throws Exception {JSONObject role=new JSONObject().put("character_book",new JSONObject().put("entries",new JSONArray().put(new JSONObject().put("keys",new JSONArray().put("Moon")).put("content","visible")).put(new JSONObject().put("constant",true).put("enabled",false).put("content","hidden"))));assertEquals("[\"visible\"]",MobileData.world(role,"MOON landing"));assertEquals("[]",MobileData.world(role,"ocean"));}
 @Test public void oversizedAndUnnamedCardsAreRejected() throws Exception {try{MobileData.parseCard(new byte[4*1024*1024+1]);fail();}catch(Exception expected){}try{MobileData.parseCard("{}".getBytes(StandardCharsets.UTF_8));fail();}catch(Exception expected){}}
 @Test public void pngCardParsesTextChunkAndRejectsTruncation() throws Exception {byte[] payload=("chara\0"+java.util.Base64.getEncoder().encodeToString("{\"name\":\"PNG role\"}".getBytes(StandardCharsets.UTF_8))).getBytes(StandardCharsets.ISO_8859_1);ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.write(new byte[]{(byte)137,80,78,71,13,10,26,10});out.writeInt(payload.length);out.writeBytes("tEXt");out.write(payload);out.writeInt(0);assertEquals("PNG role",MobileData.parseCard(bytes.toByteArray()).getString("name"));byte[] truncated=java.util.Arrays.copyOf(bytes.toByteArray(),bytes.size()-2);try{MobileData.parseCard(truncated);fail();}catch(Exception expected){}}
}
